    button:hover {
      transform: translateY(-1px);
    }

    button:focus-visible {
      outline: 3px solid rgba(91, 124, 255, 0.28);
      outline-offset: 2px;
    }

    .btn {
      min-height: 48px;
      padding: 0 18px;
      border-radius: 14px;
      font-weight: 700;
    }

    .btn-secondary {
      color: var(--text);
      background: rgba(18, 32, 51, 0.06);
    }

    .btn-secondary:hover {
      background: rgba(18, 32, 51, 0.1);
    }

    .btn-primary {
      color: #fff;
      background: linear-gradient(135deg, var(--brand) 0%, #7091ff 100%);
      box-shadow: 0 14px 28px rgba(91, 124, 255, 0.24);
    }

    .btn-danger {
      color: #fff;
      background: linear-gradient(135deg, var(--danger) 0%, var(--danger-deep) 100%);
      box-shadow: 0 14px 28px rgba(226, 77, 77, 0.24);
    }

    .trigger {
      width: 100%;
    }

    dialog {
      width: min(460px, calc(100vw - 32px));
      padding: 0;
      border: 0;
      border-radius: 26px;
      background: transparent;
      box-shadow: none;
    }

    dialog::backdrop {
      background: rgba(12, 20, 34, 0.55);
      backdrop-filter: blur(6px);
    }

    .dialog-card {
      background: var(--panel-solid);
      border-radius: 26px;
      padding: 28px;
      box-shadow: 0 28px 80px rgba(12, 20, 34, 0.35);
    }

    .dialog-icon {
      width: 52px;
      height: 52px;
      display: grid;
      place-items: center;
      border-radius: 16px;
      background: rgba(226, 77, 77, 0.12);
      color: var(--danger);
      font-size: 1.45rem;
      margin-bottom: 18px;
    }

    .dialog-copy p {
      margin-top: 0;
    }

    .dialog-actions {
      display: flex;
      justify-content: flex-end;
      gap: 12px;
      margin-top: 24px;
    }

    @media (max-width: 820px) {
      .preview-layout {
        grid-template-columns: 1fr;
      }

      .image-meta {
        flex-direction: column;
        align-items: flex-start;
